define(["core/templates"],function(Templates){"use strict";const reindexCriterion=(criterion,criterionIndex)=>{criterion.dataset.index=criterionIndex,criterion.querySelectorAll(".videorubric-level").forEach((level,levelIndex)=>{level.dataset.levelIndex=levelIndex,level.querySelectorAll("[name]").forEach(field=>{field.name=field.name.replace(/criteria\[\d+\]/,`criteria[${criterionIndex}]`).replace(/levels\[\d+\]/,`levels[${levelIndex}]`)})}),criterion.querySelectorAll(":scope > .card-body > [name], :scope > .card-body > div [name]").forEach(field=>{field.name=field.name.replace(/criteria\[\d+\]/,`criteria[${criterionIndex}]`)})},appendTemplate=async(container,template,context)=>{const{html,js}=await Templates.renderForPromise(template,context);return Templates.appendNodeContents(container,html,js),container.lastElementChild},bindCriterion=criterion=>{criterion.querySelector(".videorubric-remove-criterion")?.addEventListener("click",()=>criterion.remove()),criterion.querySelectorAll(".videorubric-remove-level").forEach(button=>{button.addEventListener("click",()=>button.closest(".videorubric-level")?.remove())}),criterion.querySelector(".videorubric-add-level")?.addEventListener("click",async()=>{const criterionIndex=Number(criterion.dataset.index),levels=criterion.querySelector(".videorubric-levels");if(!levels)return;const levelIndex=levels.querySelectorAll(".videorubric-level").length,row=await appendTemplate(levels,"mod_videorubric/rubric_level",{criterionindex:criterionIndex,index:levelIndex,id:0,label:"",description:"",points:"0"});row?.querySelector(".videorubric-remove-level")?.addEventListener("click",()=>row.remove())})},init=()=>{const container=document.getElementById("videorubric-criteria"),add=document.getElementById("videorubric-add-criterion");container&&add&&(container.querySelectorAll(".videorubric-criterion").forEach(bindCriterion),add.addEventListener("click",async()=>{const index=container.querySelectorAll(".videorubric-criterion").length,criterion=await appendTemplate(container,"mod_videorubric/rubric_criterion",{index:index,id:0,name:"",description:"",weight:"1",levels:[{criterionindex:index,index:0,id:0,label:"",description:"",points:"0"},{criterionindex:index,index:1,id:0,label:"",description:"",points:"1"}]});criterion&&bindCriterion(criterion)}),document.getElementById("videorubric-rubric-form")?.addEventListener("submit",()=>{container.querySelectorAll(".videorubric-criterion").forEach((criterion,index)=>{reindexCriterion(criterion,index)})}))};return{init:init}});
